import re

def audit(kind, name):
    if kind == "measure":
        ok = re.fullmatch(r"[A-Z0-9][A-Za-z0-9%]*( [A-Z0-9%][A-Za-z0-9%]*)*", name) is not None
        return [] if ok else ["measure format"]
    ok = re.fullmatch(r"[a-z][a-z0-9_]*", name) is not None
    return [] if ok else ["column format"]

for kind, name in [("measure", "Total Revenue"), ("measure", "total_revenue"), ("column", "unit_price"), ("column", "UnitPrice"), ("measure", "Gross Margin %")]:
    p = audit(kind, name)
    print(f"{kind} {name}: {', '.join(p) if p else 'ok'}")
